    $selectedStaff = null;
    if ($selected && $selected['staff_id']) foreach ($staffRows as $staff) if ((int)$staff['id'] === (int)$selected['staff_id']) { $selectedStaff = $staff; break; }
    $oldRoleIds = array_map('intval', old('role_ids', $selected['role_ids'] ?? []));
    $oldBranchIds = array_map('intval', old('branch_ids', $selected['branch_ids'] ?? []));
 $oldAccessScope = strtoupper(trim((string) old('access_scope', $selected['access_scope'] ?? '')));
 if (!in_array($oldAccessScope, ['PRIMARY_BRANCH','ASSIGNED_BRANCHES','COMPANY_WIDE'], true)) $oldAccessScope = 'PRIMARY_BRANCH';
    $overrideDetails = collect($selected['permission_override_details'] ?? [])->keyBy('id');
    $oldOverrides = old('permission_overrides', []);
    $explicitOverrideIds = array_keys(array_filter($oldOverrides, fn ($state) => strtoupper((string)$state) !== 'INHERIT'));
    $rolePermissionIds = array_map('intval', $selected['role_permission_ids'] ?? []);
    $effectivePermissionIds = array_map('intval', $selected['effective_permission_ids'] ?? []);
    $activeUsers = count(array_filter($users, fn ($u) => !empty($u['active'])));
    $inactiveUsers = count($users) - $activeUsers;
    $superAdmins = count(array_filter($users, fn ($u) => in_array('Super Admin', $u['role_names'] ?? [], true) || in_array('Administrator', $u['role_names'] ?? [], true)));
    $roleLabel = function (array $user): string { $roles = array_values(array_filter(array_map('strval', $user['role_names'] ?? []))); return count($roles) === 1 ? $roles[0] : (count($roles) > 1 ? 'Multiple Roles' : 'No Role'); };
