 <div class="um-section" data-et-custom-permissions="1"><div class="um-section-head">4. Custom Permissions</div><div class="um-section-body"><div class="um-perm-toolbar"><input type="search" id="et-permission-search-103335" data-et-permission-search="103336" placeholder="Search permissions..." aria-label="Search permissions"><button class="um-btn ghost" type="button" id="et-visible-inherit-103336">Set Visible to Inherited</button><button class="um-btn ghost" type="button" id="et-visible-allow-103336">Set Visible to Allow</button><button class="um-btn ghost" type="button" id="et-visible-deny-103336">Set Visible to Deny</button><button class="um-btn ghost" type="button" id="et-collapse-all-103336">Collapse All</button><button class="um-btn ghost" type="button" id="et-expand-all-103336">Expand All</button></div>@if(!$permissionStorageAvailable)<div class="um-info warn" data-et-direct-permission-fallback="1">Individual Custom Permissions are not yet available in the current database schema. Native Roles and Branch Access remain available.</div>@endif @foreach($permissions as $sectionName => $sectionPermissions)<details class="um-perm-section" data-permission-section="{{ $sectionName }}"><summary><label><input type="checkbox" class="et-section-select-all-103335" data-section="{{ $sectionName }}" {{ !$permissionStorageAvailable?'disabled':'' }}> {{ ucwords(strtolower($sectionName)) }}</label><span class="um-note">{{ count($sectionPermissions) }} permissions · <span class="et-section-count-103336">0</span> overrides</span></summary><div class="um-perm-grid">@if(!$sectionPermissions && $sectionName==='TRAVEL REPORTS')<div class="um-note">No dedicated Travel Report permissions exist yet. They will appear here when Travel Reports are added.</div>@endif @foreach($sectionPermissions as $permission) @php $pid=(int)$permission['id'];$detail=$overrideDetails->get($pid, []);$state=$oldOverrides[$pid] ?? (($detail['explicit_deny'] ?? false)?'DENY':(($detail['explicit_allow'] ?? false)?'ALLOW':'INHERIT'));$isRole=in_array($pid,$rolePermissionIds,true); @endphp<label class="um-perm-row" data-permission-row data-search="{{ e($permission['search']) }}"><select name="permission_overrides[{{ $pid }}]" data-permission-state data-section="{{ $sectionName }}" {{ !$permissionStorageAvailable?'disabled':'' }}><option value="INHERIT" {{ strtoupper((string)$state)==='INHERIT'?'selected':'' }}>Inherited</option><option value="ALLOW" {{ strtoupper((string)$state)==='ALLOW'?'selected':'' }}>Allow</option><option value="DENY" {{ strtoupper((string)$state)==='DENY'?'selected':'' }}>Deny</option></select><span><strong>{{ $permission['name'] }}</strong><small class="um-note">{{ $permission['code'] ?? '' }}</small>@if($isRole)<small class="um-note">Inherited from Native Role</small>@endif</span></label>@endforeach</div></details>@endforeach</div></div>
 <div class="um-section"><div class="um-section-head">5. Effective Access Summary</div><div class="um-section-body"><div class="um-info">Effective Permissions: {{ count($effectivePermissionIds) }} · Native Roles: {{ count($rolePermissionIds) }} · Direct Permissions: {{ $permissionStorageAvailable ? count($overrideDetails->filter(fn ($row) => ($row['explicit_allow'] ?? false) || ($row['explicit_deny'] ?? false)) ) : 'Not available' }} · Allowed Branches: {{ count($oldBranchIds) }}</div></div></div><div class="um-section"><div class="um-section-head">6. Login & Security</div><div class="um-section-body"><div class="um-form-grid"><div><label>New Password</label><input type="password" name="password" minlength="10" autocomplete="new-password"></div><div><label>Confirm Password</label><input type="password" name="password_confirmation" minlength="10" autocomplete="new-password"></div></div><div class="um-note">Leave blank to retain the current password.</div></div></div><div class="um-footer"><a class="um-btn" href="{{ route('administration.erp-user-management.index') }}">Cancel</a><button class="um-btn ghost" type="reset">Reset Changes</button><button class="um-btn primary" type="submit">Save User Account</button></div></form></div></div>
