<script>
document.addEventListener('DOMContentLoaded',function(){
 const root=document.getElementById('et-user-management-103175'); if(!root)return;
 const template=document.getElementById('et-role-template-103335'); const state=document.getElementById('et-template-state-103335');
 const boxes=()=>Array.from(root.querySelectorAll('[data-permission-state]'));
 const refresh=()=>root.querySelectorAll('[data-permission-section]').forEach(section=>{const allBoxes=Array.from(section.querySelectorAll('[data-permission-state]'));const selected=allBoxes.filter(b=>b.value!=='INHERIT').length;allBoxes.forEach(box=>box.closest('[data-permission-row]')?.setAttribute('data-state',box.value));const select=section.querySelector('.et-section-select-all-103335');const count=section.querySelector('.et-section-count-103336');if(select){select.checked=allBoxes.length>0&&selected===allBoxes.length;select.indeterminate=selected>0&&selected<allBoxes.length;}if(count)count.textContent=String(selected);});
 const applyTemplate=(reset)=>{const name=template?.value||'Custom Access';if(name==='Custom Access'){if(state)state.textContent='Custom Access · Customized';return;}const config=(@json($roleTemplates))[name]||{include:[],exclude:[],allowed_sections:[]};boxes().forEach(box=>{if(box.disabled)return;const row=box.closest('[data-permission-row]');const text=(row?.dataset.search||'').toLowerCase();const section=box.dataset.section||'';const sectionAllowed=(config.allowed_sections||[]).includes(section);const include=(config.include||[]).some(term=>term==='*'||text.includes(String(term).toLowerCase()));const exclude=(config.exclude||[]).some(term=>text.includes(String(term).toLowerCase()));box.value=sectionAllowed&&include&&!exclude?'ALLOW':'INHERIT';});if(state)state.textContent=name+(reset?'':'');refresh();};
 document.getElementById('et-apply-template-103335')?.addEventListener('click',()=>applyTemplate(false));document.getElementById('et-reset-template-103335')?.addEventListener('click',()=>applyTemplate(true));
 root.querySelectorAll('.et-section-select-all-103335').forEach(select=>select.addEventListener('change',()=>{root.querySelectorAll('[data-permission-state][data-section="'+CSS.escape(select.dataset.section)+'"]').forEach(box=>{const row=box.closest('[data-permission-row]');if(!box.disabled&&!row?.hidden)box.value=select.checked?'ALLOW':'INHERIT';});refresh();}));boxes().forEach(box=>box.addEventListener('change',refresh));
 const setVisible=(value)=>{const open=root.querySelector('.um-perm-section[open]');if(!open)return;open.querySelectorAll('[data-permission-state]').forEach(box=>{const row=box.closest('[data-permission-row]');if(!box.disabled&&!row?.hidden)box.value=value;});refresh();}; document.getElementById('et-visible-inherit-103336')?.addEventListener('click',()=>setVisible('INHERIT'));document.getElementById('et-visible-allow-103336')?.addEventListener('click',()=>setVisible('ALLOW'));document.getElementById('et-visible-deny-103336')?.addEventListener('click',()=>setVisible('DENY')); const search=root.querySelector('[data-et-permission-search]');search?.addEventListener('input',()=>{const needle=search.value.trim().toLowerCase();root.querySelectorAll('[data-permission-row]').forEach(row=>{row.hidden=needle!==''&&!String(row.dataset.search||'').toLowerCase().includes(needle);});root.querySelectorAll('[data-permission-section]').forEach(section=>{if(needle!==''&&section.querySelector('[data-permission-row]:not([hidden])'))section.open=true;});refresh();});
 const sectionHeads=Array.from(root.querySelectorAll('.um-section-head'));const target=(text,id)=>{const head=sectionHeads.find(h=>h.textContent.includes(text));if(head)head.closest('.um-section').id=id;};target('1. Identity','et-identity-section-103336');target('5. Effective Access','et-effective-access-section-103336');target('6. Login & Security','et-login-security-section-103336');const tabs=Array.from(root.querySelectorAll('.um-tab'));[['Profile & Access','et-identity-section-103336'],['Effective Permissions','et-effective-access-section-103336'],['Login & Security','et-login-security-section-103336']].forEach(([label,id])=>{const tab=tabs.find(t=>t.textContent.trim()===label);if(tab){tab.setAttribute('role','button');tab.setAttribute('tabindex','0');tab.addEventListener('click',()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'}));}});refresh();
});
const permissionRoot=document.getElementById('et-user-management-103175');if(permissionRoot){document.getElementById('et-collapse-all-103336')?.addEventListener('click',()=>permissionRoot.querySelectorAll('.um-perm-section').forEach(section=>{section.open=false;}));document.getElementById('et-expand-all-103336')?.addEventListener('click',()=>permissionRoot.querySelectorAll('.um-perm-section').forEach(section=>{section.open=true;}));const summaryHead=Array.from(permissionRoot.querySelectorAll('.um-section-head')).find(head=>head.textContent.includes('5. Effective Access Summary'));const summaryInfo=summaryHead?.parentElement.querySelector('.um-info');if(summaryInfo){const cards=document.createElement('div');cards.className='um-effective-cards';summaryInfo.textContent.split('·').map(part=>part.trim()).filter(Boolean).forEach(part=>{const split=part.split(':');const card=document.createElement('div');card.className='um-effective-card';card.innerHTML='<div class="um-metric-label">'+split.shift().trim()+'</div><div class="um-metric-value">'+split.join(':').trim()+'</div>';cards.appendChild(card);});summaryInfo.replaceWith(cards);}}
if(permissionRoot){permissionRoot.querySelectorAll('select[data-permission-state]').forEach(select=>{const group=document.createElement('div');group.className='um-tristate';group.setAttribute('role','radiogroup');group.setAttribute('aria-label','Permission override');['INHERIT','ALLOW','DENY'].forEach(value=>{const button=document.createElement('button');button.type='button';button.className='um-tristate-option';button.dataset.value=value;button.textContent=value==='INHERIT'?'Inherited':value.charAt(0)+value.slice(1).toLowerCase();button.setAttribute('aria-pressed',select.value===value?'true':'false');button.addEventListener('click',()=>{select.value=value;select.dispatchEvent(new Event('change',{bubbles:true}));group.querySelectorAll('button').forEach(item=>item.setAttribute('aria-pressed',item.dataset.value===value?'true':'false'));});group.appendChild(button);});select.hidden=true;select.parentNode.insertBefore(group,select);});}
</script>
@endsection
